mapper.select:
SELECT
    maqc.*,
    mbp.name AS process_name
FROM mes_artifact_quota_config maqc
LEFT JOIN mes_building_process mbp ON mbp.bool_delete_enum = 0 AND mbp.id = maqc.process_id
WHERE maqc.bool_delete_enum = 0

    AND maqc.id = #{id}


    AND FIND_IN_SET(#{workshopId}, maqc.workshop_ids) > 0


    AND FIND_IN_SET(#{classId}, maqc.artifact_class_ids) > 0


    
    AND maqc.quota_number LIKE #{quotaNumberLike}


    AND maqc.process_id = #{processId}


    AND maqc.status = #{status}
